#!/usr/bin/env python3
"""
Round 184o (culprits-tiles-more), 5 October 2026.

Fixes three scripts from the 5 October refresh: burned_area.py (reads
MCD64CMQ from the University of Maryland's SFTP server, not NASA's catalogue),
bii_nhm.py (a refused download is written down, not a failure; reads a copy
uploaded by hand to bii/download/), forest500_map.py (Natural Earth's label
point where it lists no town). Each file is written only if it differs.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, sys

FILES = {'scripts/burned_area.py': '', 'scripts/bii_nhm.py': '', 'scripts/forest500_map.py': ''}


def main():
    if not pathlib.Path("scripts").is_dir():
        sys.exit("round184o_tiles: run from the culprits-tiles-more repository root")
    changed = 0
    for path, b64 in FILES.items():
        data = base64.b64decode(b64)
        p = pathlib.Path(path)
        if p.exists() and p.read_bytes() == data:
            continue
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(data)
        changed += 1
        print(f"round184o_tiles: wrote {path}")
    if not changed:
        print("round184o_tiles: already applied")


if __name__ == "__main__":
    main()
